mapper.update:
{CALL
    DECLARE
        v_sql varchar2(500);
    BEGIN
        v_sql := 'CREATE SEQUENCE ${tableName}_SEQ START WITH 1  MAXVALUE 99999999 MINVALUE 1 CYCLE CACHE 20 NOORDER';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX1 ON ${tableName}(STATUS, REQDATE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX2 ON ${tableName}(PHONE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX3 ON ${tableName}(RSLT, REQDATE)';
        execute immediate v_sql;
    END
}

{CALL
    DECLARE
        v_sql varchar2(500);
    BEGIN
        v_sql := 'CREATE INDEX ${tableName}_IDX1 ON ${tableName}(PHONE)';
        execute immediate v_sql;

        v_sql := 'CREATE INDEX ${tableName}_IDX2 ON ${tableName}(RSLT, REQDATE)';
        execute immediate v_sql;
    END
}

UPDATE ${tableName}
SET
    STATUS = CASE WHEN STATUS = '3' THEN STATUS ELSE #{parameter.messageStatus} END,
    TERMINATEDDATE = SYSDATE
    , SENTDATE = TO_DATE(#{parameter.sentDate}, 'YYYYMMDDHH24MISS')
    , ROUTE_ID = #{parameter.routeId}
    , RSLT = #{parameter.doneCode}
    , REPORTDATE = TO_DATE(#{parameter.doneDate}, 'YYYYMMDDHH24MISS')
    , TELCOINFO = #{parameter.doneTelco}
    , FILE_CNT_REAL = #{parameter.realContentsCount}
WHERE
    MSGKEY IS NULL
    MSGKEY = #{parameter.key}

DELETE FROM ${tableName}
WHERE
    MSGKEY IS NULL
    MSGKEY = #{parameter.key}
